  "confidence": "high",
  "uncertainties": [],
  "risk": {
    "level": "medium",
    "touches": ["rpc_api", "p2p"],
    "why": "Bugs in delay scheduling or re-validation could cause transactions to be silently dropped or fail to broadcast over private connections, while the lack of persistence can lead to forgotten transactions on node restart."
  }
}
